pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address baseToken, address nft, uint128 virtualBase, uint128 virtualNft, uint56 changeFee, uint16 feeRate, bytes32 root, bool useStolen, bool payRoyalties) public {
        vm.assume(baseToken != address(0));
        vm.assume(feeRate <= 5000);
        vm.recordLogs();
        c.initialize(baseToken, nft, virtualBase, virtualNft, changeFee, feeRate, root, useStolen, payRoyalties);
        Vm.Log[] memory entries = vm.getRecordedLogs();
        bool emittedMatch;
        for (uint i = 0; i < entries.length; i++) {
            if (entries[i].topics.length > 0 && entries[i].topics[0] == keccak256("Initialize(address,address,uint128,uint128,uint56,uint16,bytes32,bool,bool)")) {
                emittedMatch = abi.decode(entries[i].data, (address,address,uint128,uint128,uint56,uint16,bytes32,bool,bool))._0 == c.baseToken();
                break;
            }
        }
        assertTrue(emittedMatch);
    }
}

