pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint256 baseTokenAmount, uint8 feeRate) public {
        // baseTokenAmount > 0; feeRate <= 5000
        vm.assume(baseTokenAmount > 0);
        vm.assume(feeRate <= 50); // 5000 bps; use uint8 for fuzz efficiency
        uint16 _feeRate = uint16(feeRate) * 100;
        // initialize with a non-zero base token (use a token we deploy)
        MockERC20 token = new MockERC20();
        c.initialize(address(token), address(0x1), 1e18, 1e18, 0, _feeRate, bytes32(0), false, false);
        // deposit call without msg.value should succeed (baseToken != address(0))
        vm.prank(address(this));
        token.mint(address(this), baseTokenAmount);
        token.approve(address(c), baseTokenAmount);
        vm.prank(address(this));
        try c.deposit(new uint256[](0), baseTokenAmount) {
            assertTrue(true);
        } catch {
            assertTrue(false);
        }
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }
    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "insufficient allowance");
        require(balanceOf[from] >= amount, "insufficient balance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
    function decimals() external pure returns (uint8) { return 18; }
}

