pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address _baseToken2) public {
        address _baseToken1 = address(0x1);
        vm.assume(_baseToken1 != _baseToken2);
        address _nft = address(0x2);
        uint128 _virtualBaseTokenReserves = 100;
        uint128 _virtualNftReserves = 50;
        uint56 _changeFee = 100;
        uint16 _feeRate = 100;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;

        c.initialize(_baseToken1, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties);
