pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 changeFee) public {
        // 1. Restrict to admissible domain: feeRate <= 5000
        // Note: the changeFee parameter has no inherent limit, but we must ensure feeRate is valid.
        uint16 feeRate = 100; // any valid feeRate <= 5000

        // 2. Setup: we need to call initialize with the given changeFee.
        // The contract's constructor sets factory, royaltyRegistry, stolenNftOracle.
        // initialize can only be called once; we do it directly.
        c.initialize(
            address(0),  // _baseToken
            address(0),  // _nft
            1,           // _virtualBaseTokenReserves
            1,           // _virtualNftReserves
            changeFee,   // _changeFee
            feeRate,     // _feeRate
            bytes32(0),  // _merkleRoot
            false,       // _useStolenNftOracle
            false        // _payRoyalties
        );

        // 3. Assert: changeFee stored in the contract must equal the passed argument.
        // The buggy version omits the assignment, so it stays at 0.
        assertEq(c.changeFee(), changeFee);
    }
}

