pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 changeFeeParam) public {
        // Bound to valid uint56 range
        changeFeeParam = uint56(bound(changeFeeParam, 0, type(uint56).max));

        // Use fuzzed changeFeeParam as the parameter to initialize
        // All other parameters set to valid dummy values
        c.initialize(
            address(0), // _baseToken
            address(0), // _nft
            1,          // _virtualBaseTokenReserves
            1,          // _virtualNftReserves
            changeFeeParam, // _changeFee
            0,          // _feeRate
            bytes32(0), // _merkleRoot
            false,      // _useStolenNftOracle
            false       // _payRoyalties
        );

        // The general rule: changeFee should equal the parameter passed to initialize.
        // The buggy version always sets changeFee = 1, violating this for any changeFeeParam != 1.
        // Also check that when changeFeeParam is 1, it happens to match (no false failure).
        if (changeFeeParam == 1) {
            // Both correct and buggy set changeFee to 1; skip assertion to avoid false failure.
            // We let the fuzzer find the violating case where changeFeeParam != 1.
        } else {
            assertEq(c.changeFee(), changeFeeParam, "changeFee should equal the initialization parameter");
        }
    }
}

